#[rustfmt::skip]
fn is_typed_array_constructor(name: &str) -> bool {
    matches!(name, "Int8Array" | "Uint8Array" | "Uint8ClampedArray" | "Int16Array" | "Uint16Array"
            | "Int32Array" | "Uint32Array" | "Float32Array" | "Float64Array"
            | "BigInt64Array" | "BigUint64Array")
}

/// Whether a `new Date(...)` call is pure.
///
/// `Date` is pure with no arguments, or when every argument is a numeric or string literal.
/// Unknown variable references (or any other argument) may run user code during coercion.
fn is_pure_date_constructor(args: &[Argument<'_>]) -> bool {
    args.iter().all(|arg| {
        matches!(
            arg.as_expression(),
            Some(Expression::NumericLiteral(_) | Expression::StringLiteral(_))
        )
    })
}

/// Whether a `new Buffer(...)` call is pure.
///
/// `Buffer` is pure with no arguments or a single numeric literal (an allocation length).
/// Unknown variable references (or any other argument) read or coerce their contents.
fn is_pure_buffer_constructor(args: &[Argument<'_>]) -> bool {
    args.iter().all(|arg| matches!(arg.as_expression(), Some(Expression::NumericLiteral(_))))
}

/// Whether a `new Int8Array(...)` (or other TypedArray) call is pure.
///
/// TypedArray constructors are pure with no arguments, a numeric literal (a length), or a plain
/// object literal without a custom `Symbol.iterator`. Unknown variable references and object
/// literals defining a custom iterator may run user code.
fn is_pure_typed_array_constructor<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return false;
    }
    match args.first().and_then(Argument::as_expression) {
        None => true,
        Some(Expression::NumericLiteral(_)) => true,
        Some(Expression::ObjectExpression(obj)) => !maybe_object_with_custom_iterator(obj),
        _ => false,
    }
}

